import {drawMon,flame} from './art.mjs';
import {drawPixel,drawStream,drawImpact} from './pixel-fx.mjs';
const W=480,H=270,TAU=Math.PI*2,cache=new Map(),clamp=n=>Math.max(0,Math.min(1,n)),ease=n=>{n=clamp(n);return n*n*(3-2*n)},noise=(x,y=0)=>{let n=Math.imul(x+41,374761393)^Math.imul(y+17,668265263);n=Math.imul(n^(n>>>13),1274126177);return((n^(n>>>16))>>>0)/4294967296};
const rect=(c,x,y,w,h,col)=>{c.fillStyle=col;c.fillRect(Math.round(x),Math.round(y),Math.ceil(w),Math.ceil(h))};
function poly(c,pts,col){c.fillStyle=col;c.beginPath();pts.forEach(([x,y],i)=>i?c.lineTo(Math.round(x),Math.round(y)):c.moveTo(Math.round(x),Math.round(y)));c.closePath();c.fill()}
function disc(c,x,y,r,col){for(let yy=-r;yy<=r;yy++){const xx=Math.sqrt(Math.max(0,r*r-yy*yy));rect(c,x-xx,y+yy,xx*2,1,col)}}
function circle(c,x,y,r,col,width=1){c.strokeStyle=col;c.lineWidth=width;c.beginPath();c.arc(x,y,r,0,TAU);c.stroke()}
function cloud(c,x,y,w,col){rect(c,x,y,w,7,col);rect(c,x+w*.1,y-5,w*.75,8,col);rect(c,x+w*.22,y-9,w*.4,8,col)}
function pillar(c,x,y,height,col='#667078'){rect(c,x-9,y-height,18,height,col);rect(c,x-12,y-height-4,24,5,'#c0bca5');rect(c,x-12,y-3,24,6,'#a09f90');rect(c,x-6,y-height+3,3,height-8,'#89949b');rect(c,x+5,y-height+3,2,height-8,'#3c4c60')}
function tree(c,x,y,size=1,palette=['#163d3c','#2c5a48','#527852']){rect(c,x-3*size,y-23*size,6*size,26*size,'#574a41');for(let i=0;i<3;i++){rect(c,x-(17-i*3)*size,y-(24+i*9)*size,(34-i*6)*size,15*size,palette[i]);rect(c,x-(14-i*3)*size,y-(27+i*9)*size,(28-i*6)*size,5*size,palette[(i+1)%3])}}
function floor(c,story,from=174,palette=['#394854','#475662','#52616b']){for(let y=from;y<H;y+=7)for(let x=0;x<W;x+=9){const col=palette[Math.floor(noise(x+story.id,y)*palette.length)];rect(c,x,y,8,6,col);if(noise(x,y+story.id)>.85)rect(c,x+1,y+2,3,1,palette[2])}}
function ocean(c,t,storm=false){rect(c,0,146,W,124,storm?'#1d344e':'#255778');for(let y=149;y<H;y+=6)for(let x=-20;x<W;x+=27){const dx=Math.sin(t*1.3+y*.1)*8;rect(c,x+dx+noise(x,y)*8,y,8+noise(y,x)*13,1,y%12?'#43839c':'#67a6b3')}}
function tower(c,x,base,height){const top=base-height;rect(c,x-31,top,62,height,'#556877');rect(c,x-28,top,13,height,'#83908e');rect(c,x+23,top,8,height,'#39495c');for(let y=top+7;y<base;y+=10){rect(c,x-29,y,57,1,'#3e5263');for(let xx=x-22;xx<x+25;xx+=16)rect(c,xx+(y%20?6:0),y+1,1,8,'#95a2a0')}for(let i=0;i<4;i++){rect(c,x-36,top+i*28,72,4,'#9da998');rect(c,x-35,top+i*28+4,70,2,'#384e60');rect(c,x-8,top+i*28+8,16,15,'#243b50')}rect(c,x-38,top-7,76,8,'#a5b09e');for(let i=0;i<7;i++)rect(c,x-36+i*11,top-17,7,13,'#849590');rect(c,x-15,base-29,30,30,'#1c3446');for(let i=0;i<height*1.3;i++){const xx=x-29+noise(i,height)*57,yy=top+noise(height,i)*height;rect(c,xx,yy,1+noise(i,2)*2,1,i%3?'#647b85':'#a7afa1')}for(let i=0;i<5;i++)rect(c,x-21+i*10,top-2,4,2,'#657b7a')}
function backdrop(story){const key=story.id;let bg=cache.get(key);if(bg)return bg;bg=document.createElement('canvas');bg.width=W;bg.height=H;const c=bg.getContext('2d'),s=story.scene,night=['moon','cosmos','origin','distortion','city','lab'].includes(s);rect(c,0,0,W,H,night?'#101c32':'#263a53');for(let y=0;y<150;y+=12)rect(c,0,y,W,12,night?['#101c32','#142239','#1a2c43'][Math.floor(y/50)]:['#263a53','#314a61','#4f6878'][Math.floor(y/50)]);
 for(let layer=0;layer<3;layer++){const pts=[[0,170]];for(let x=-10;x<=W+20;x+=22)pts.push([x,105+layer*19-noise(x+story.id,layer)*45]);pts.push([W,190],[0,190]);poly(c,pts,['#203044','#2c4257','#3c5767'][layer])}
 if(['cosmos','origin','moon','distortion','city'].includes(s)){for(let i=0;i<95;i++){const x=noise(i,story.id)*W,y=noise(story.id,i)*173;rect(c,x,y,i%8?1:2,1,i%3?'#a8b4ce':'#e7d7b8')}if(s==='moon'){disc(c,375,54,27,'#c3c3d6');disc(c,387,47,25,'#1a2c43')}}
 if(['ocean','island','sky-pillar','lake'].includes(s)){ocean(c,0,s==='sky-pillar');if(s==='island'||s==='sky-pillar'){poly(c,[[125,218],[159,182],[318,178],[368,219],[286,244],[171,239]],'#2c4a4a');poly(c,[[139,209],[175,185],[303,183],[341,210],[283,226],[182,224]],'#687e69')}if(s==='lake'){floor(c,story,226,['#355257','#3e625f','#4d746c']);for(const x of[40,90,405,445])tree(c,x,174,.9)}}
 else if(['forest','flower','field'].includes(s)){floor(c,story,163,['#294c44','#365b49','#456c4e']);for(let i=0;i<17;i++)tree(c,12+i*29,170+(i%3)*12,1+noise(i,story.id)*.35);rect(c,165,192,150,47,'#677359');rect(c,170,187,140,8,'#859475');if(s==='flower')for(let i=0;i<90;i++){const x=noise(i,4)*W,y=178+noise(i,story.id)*92;rect(c,x,y,3,2,i%3?'#d7a9b9':'#d4cd9a')}}
 else if(s==='volcano'){floor(c,story,157,['#453943','#56454b','#68534f']);poly(c,[[45,165],[117,64],[198,166]],'#453441');poly(c,[[99,91],[117,64],[138,92],[131,105],[109,105]],'#e19a5b');for(let i=0;i<7;i++){const x=40+i*69;poly(c,[[x,185],[x+19,207],[x+5,233],[x+25,270],[x+35,270],[x+14,234],[x+28,207],[x+9,182]],'#bc6047');rect(c,x+9,209,4,15,'#efad62')}}
 else if(s==='ice'){floor(c,story,164,['#54768d','#6f94a4','#90b4bd']);for(let i=0;i<10;i++){const x=i*53-13,hh=27+noise(i,story.id)*61;poly(c,[[x,190],[x+11,190-hh],[x+21,190-hh*.7],[x+27,190]],i%2?'#9bcbd5':'#b4dce0');rect(c,x+10,191-hh,3,hh-5,'#d2ebea')}}
 else if(s==='lab'||s==='power'||s==='city'){rect(c,0,73,W,107,'#26364c');for(let x=8;x<W;x+=34){rect(c,x,83,26,72,'#344961');rect(c,x+3,87,20,15,s==='power'?'#bcb56f':'#62969c');for(let j=0;j<4;j++)rect(c,x+4,122+j*7,17,2,'#17263d')}floor(c,story,180,['#35475a','#405368','#52657a']);if(s==='lab'){rect(c,207,71,66,120,'#8b98a6');rect(c,211,74,58,111,'#305776');rect(c,217,80,10,97,'#72a6bb');rect(c,204,184,72,9,'#a7ada3')}if(s==='city')for(let x=20;x<W;x+=45)rect(c,x,184+(x%4)*9,28,1,'#959ad8')}
 else if(s==='theatre'){floor(c,story,180,['#625043','#735f4e','#8b7055']);rect(c,32,48,416,135,'#273047');for(const x of[32,398]){rect(c,x,48,50,136,'#774b60');for(let i=0;i<5;i++)rect(c,x+i*10,48,3,136,'#a46e7c')}rect(c,80,48,320,8,'#c8a56f');rect(c,90,180,300,9,'#be9a68')}
 else if(s==='village'){floor(c,story,169,['#4d5054','#5e615c','#6e7165']);for(const x of[20,370]){rect(c,x,109,90,73,'#756355');poly(c,[[x-8,110],[x+45,70],[x+99,110]],'#424455');rect(c,x+34,140,23,42,'#2d3446');rect(c,x+9,124,15,17,'#d0af7d')}rect(c,151,89,178,7,'#a15f59');rect(c,162,84,7,100,'#835956');rect(c,310,84,7,100,'#835956');rect(c,144,79,192,6,'#ca8b6f')}
 else{floor(c,story,174,['#384b5b','#4c6071','#5f7280']);for(const x of[47,100,380,433])pillar(c,x,187,67+noise(x,story.id)*32);rect(c,168,190,144,30,'#596d78');rect(c,174,186,132,6,'#b2b9ac');if(s==='distortion'){c.save();c.translate(W,180);c.rotate(Math.PI);for(const x of[120,320])pillar(c,x,130,80,'#6d5b7f');c.restore()}if(s==='origin')for(let i=0;i<11;i++)rect(c,80+i*13,243-i*7,320-i*22,4,i%2?'#baa777':'#e5d5a5')}
 if(s==='tower')tower(c,240,217,139);if(s==='sky-pillar')tower(c,240,220,143);if(['temple','ruins','cave','crystal','desert'].includes(s)){rect(c,191,91,98,92,'#24394d');rect(c,186,85,108,8,'#a0adab');for(let i=0;i<7;i++)rect(c,200+i*12,98,2,78,'#526c77')}
 if(cache.size>12)cache.delete(cache.keys().next().value);cache.set(key,bg);return bg;
}
function signature(c,story,t,intensity,reduced){const color=story.color,e=story.effect,amount=reduced?10:30;c.save();c.globalAlpha=intensity;
 if(/clock|origin|glyph|chains|metal|gears|gravity|coil|magnet|totem|target|vessel|tablets/.test(e)){for(let j=0;j<3;j++){const r=33+j*19;circle(c,240,151,r,color,1);for(let i=0;i<12;i++){const a=i*TAU/12+t*(e==='clock'?.15:.07)*(j%2?1:-1),x=240+Math.cos(a)*r,y=151+Math.sin(a)*r;rect(c,x-1,y-2,2,4,color)}}if(e==='clock'){c.strokeStyle=color;c.lineWidth=2;c.beginPath();c.moveTo(240,151);c.lineTo(240+Math.sin(t)*30,151-Math.cos(t)*30);c.moveTo(240,151);c.lineTo(262,160);c.stroke()}}
 else if(/rift|inversion|rings|nightmare|shadow|mist|redstorm/.test(e)){for(let j=0;j<8;j++){const r=30+j*6;c.strokeStyle=j%2?color:'#7072a2';c.lineWidth=2;c.beginPath();c.ellipse(240,148,r*.7,r,Math.sin(t*.3)*.15+j*.06,0,TAU);c.stroke()}}
 else if(/blade|sword|iceblade|fist|shield|waterblade/.test(e)){if(e==='shield'){poly(c,[[240,72],[273,90],[268,132],[240,153],[212,132],[207,90]],color);poly(c,[[240,81],[264,95],[260,126],[240,142],[220,126],[216,95]],'#31445b')}else{poly(c,[[239,72],[245,84],[243,133],[247,138],[244,142],[240,138],[236,142],[233,138],[237,133],[235,84]],color);rect(c,226,132,28,3,'#dbbd80')}}
 else if(/rainbow|prism|life|terastal/.test(e)){for(let j=0;j<7;j++){c.strokeStyle=['#c77a89','#d7a075','#dfcd89','#96c7a7','#83b7d3','#9a9bd2','#c0a1ce'][j];c.lineWidth=3;c.beginPath();c.arc(240,173,55+j*4,Math.PI,TAU);c.stroke()}}
 else if(e==='dna'){for(let i=0;i<28;i++){const y=75+i*5,a=i*.4+t;const x=240+Math.sin(a)*27;rect(c,x,y,4,3,'#edaa8c');rect(c,480-x,y,4,3,'#8fc6d8');if(i%3===0)rect(c,Math.min(x,480-x),y+1,Math.abs(480-x*2),1,'#b8bfd1')}}
 else if(/crystal|diamond|cells|dragon|beads|peach/.test(e)){for(let j=0;j<7;j++){const a=j*TAU/7+t*.2,x=240+Math.cos(a)*64,y=150+Math.sin(a)*34;poly(c,[[x,y-11],[x+6,y],[x,y+11],[x-6,y]],j%2?color:'#e0dae9')}}
 else if(/sun|stars|victory|will/.test(e)){for(let j=0;j<12;j++){const a=j*TAU/12+t*.1,x=240+Math.cos(a)*45,y=139+Math.sin(a)*45;poly(c,[[x,y-5],[x+2,y-1],[x+6,y],[x+2,y+2],[x,y+6],[x-2,y+2],[x-5,y],[x-1,y-1]],color)}}
 else if(e==='notes'){for(let j=0;j<9;j++){const a=j*2.399+t*.8,x=240+Math.cos(a)*61,y=142+Math.sin(a)*35;rect(c,x,y,5,3,color);rect(c,x+4,y-9,1,11,color);rect(c,x+4,y-9,5,2,color)}}
 else if(e==='masks'){for(let j=0;j<4;j++){const x=170+j*47,y=119+Math.sin(t+j)*7;poly(c,[[x-9,y-12],[x+9,y-12],[x+12,y+5],[x,y+13],[x-12,y+5]],['#91c886','#e9a271','#9ac6d2','#bcb6d7'][j]);rect(c,x-7,y-2,4,3,'#273544');rect(c,x+3,y-2,4,3,'#273544')}}
 else for(let i=0;i<amount;i++){const a=i*2.399+t*.3,r=28+noise(i,story.id)*59,x=240+Math.cos(a)*r,y=152+Math.sin(a)*r*.6-Math.sin(t*.8+i)*11;if(/snow|frost|snowhoof/.test(e)){rect(c,x,y,5,1,color);rect(c,x+2,y-2,1,5,color)}else if(/leaf|leaves|petals|spring|scales|harvest|roots|vines/.test(e)){poly(c,[[x-3,y],[x,y-4],[x+4,y-2],[x+1,y+2]],color)}else if(/bolt|reactor|dash|future/.test(e)){poly(c,[[x,y-9],[x+4,y-9],[x+1,y-2],[x+6,y-2],[x-3,y+10],[x,y+1],[x-4,y+1]],color)}else if(/tide|bubble|pearl|ripple|water|whirlpool/.test(e))circle(c,x,y,3+noise(i)*4,color);else if(/ember|fire|magma|tectonic|forge|steam/.test(e))flame(c,x,y,3+noise(i)*3,reduced?0:t+i,color);else rect(c,x,y,2+noise(i)*2,2,color)}c.restore();
}
function atmosphere(c,story,t,reduced){if(['ocean','island','lake'].includes(story.scene)&&!reduced)for(let y=150;y<(story.scene==='lake'?225:270);y+=8)for(let x=0;x<W;x+=31){if(story.scene==='island'&&x>115&&x<371&&y>177&&y<247)continue;rect(c,x+Math.sin(t+y)*4,y,8,1,'#5998ae')}if(['storm','ocean','power','sky-pillar'].includes(story.scene)){for(let i=0;i<7;i++)cloud(c,((i*91-t*4)%620)-80,22+i%3*12,75,'#25364d');if(!reduced)for(let i=0;i<45;i++){const x=(noise(i,story.id)*510+t*14)%510,y=(noise(story.id,i)*270+t*76)%270;rect(c,x,y,1,4,'#6b879d')}}if(story.scene==='volcano'&&!reduced)for(let i=0;i<25;i++){const x=noise(i,story.id)*480,y=260-((t*18+noise(story.id,i)*220)%230);rect(c,x,y,2,2,i%2?'#ca7b5e':'#e6bc78')}}
function rayquaza(c,key,t,reduced){for(let i=0;i<4;i++){const pts=[[0,139+i*8]];for(let x=0;x<=480;x+=30)pts.push([x,105+i*11-noise(x,i)*25]);pts.push([480,150+i*8]);poly(c,pts,['#192b40','#20364a','#294255','#314e5c'][i])}for(let i=0;i<9;i++)cloud(c,((i*72-(reduced?0:t*4))%650)-100,20+i%3*13,73,'#273b50');const act=t<4?0:t<8?1:t<11.5?2:3;c.save();if(act===0){ocean(c,reduced?0:t,true);for(let i=0;i<6;i++)cloud(c,i*94-40-(reduced?0:t*3),30+i%2*14,105,'#26364d');poly(c,[[132,235],[181,199],[299,199],[345,235]],'#57716c');tower(c,240,228-(reduced?0:ease(t/4)*15),149);}
 else if(act===1){ocean(c,reduced?0:t,true);poly(c,[[0,178],[83,147],[187,170],[216,236],[0,270]],'#70534b');for(let i=0;i<7;i++)flame(c,24+i*26,224+i%2*12,5,reduced?0:t+i);drawMon(c,'383',118,204,142,'Attack',2,t,{progress:(t-4)%1});drawMon(c,'382',359,208,148,'Attack',6,t,{progress:(t-4)%1});if(t>4.5){const split={x:240+Math.sin(t*2)*11,y:174};drawStream(c,{type:'fire',slug:'flamethrower'},{x:151,y:181},split,t,{width:13,reducedMotion:reduced});drawStream(c,{type:'water',slug:'hydro-pump'},{x:330,y:181},split,t,{width:13,reducedMotion:reduced});drawImpact(c,{type:'electric'},split,((t-4.5)*.8)%1,{scale:.7,reducedMotion:reduced})}}
 else{const q=ease((t-8)/3.5);ocean(c,reduced?0:t,true);for(let i=0;i<7;i++)cloud(c,i*85-70-(reduced?0:q*45),18+i%2*15,91,'#263d4d');c.globalAlpha=.2+q*.2;poly(c,[[229,0],[251,0],[304,221],[176,221]],'#87e8b1');c.globalAlpha=1;for(let i=0;i<18;i++){const y=(noise(i,6)*200+t*15)%220;rect(c,240+Math.sin(i*2.399+t*.4)*21,y,2,3,'#b6efb8')}if(act===2){c.save();c.globalAlpha=q;c.filter='brightness('+(reduced?1:.15+q*.85)+')';drawMon(c,key,240,-40+ease(q)*189,180,'Idle',0,t);c.restore();drawMon(c,'383',91,247,73,'Idle',2,t);drawMon(c,'382',391,247,82,'Idle',6,t)}else{poly(c,[[120,252],[159,214],[322,214],[362,252]],'#6d8a76');rect(c,152,215,176,5,'#b2c6a2');for(let i=0;i<10;i++)rect(c,162+i*16,220,2,17,'#9ab590');drawMon(c,key,240,184+(reduced?0:Math.sin(t*.8)*3),232,'Idle',0,t);signature(c,{id:384,effect:'glyphs',color:'#9ee9b1'},t,.5,reduced)}}if(!reduced)for(let i=0;i<(act<2?35:14);i++){const x=(noise(i,21)*500+t*13)%500,y=(noise(i,39)*250+t*72)%250;rect(c,x,y,1,4,act<2?'#718a9f':'#729c96')}c.restore();return act;
}
export function drawLegendaryFrame(c,story,key,t,reduced=false){c.setTransform(1,0,0,1,0,0);c.imageSmoothingEnabled=false;rect(c,0,0,W,H,'#101c30');if(story.id===384)return rayquaza(c,key,t,reduced);const act=Math.min(3,Math.floor(t/3)),q=(t%3)/3;c.save();const zoom=reduced?1:act===3?1.08+ease(q)*.04:1+ease(q)*.025;c.translate(240,135);c.scale(zoom,zoom);c.translate(-240,-135);c.drawImage(backdrop(story),0,0);atmosphere(c,story,t,reduced);if(story.scene==='sky-pillar')tower(c,240,220,143);if(story.scene==='lake'){c.globalAlpha=.45;circle(c,240,197,33+Math.sin(t)*5,story.color);c.globalAlpha=1}
 if(act>=1)signature(c,story,reduced?1:t,act===1?ease(q)*.8:act===2?.55:.3,reduced);
 if(act>=2){const entry=ease(act===2?q:1),fly=/flight|dash|ancient|future/.test(story.effect),x=fly?70+entry*170:240,y=/tide|bubble|pearl|whirlpool/.test(story.effect)?255-entry*64:225-entry*40;const size=act===3?185+ease(q)*8:140+entry*45;c.save();c.globalAlpha=entry;c.filter='brightness('+(reduced?1:act===2?.18+entry*.82:1)+')';drawMon(c,key,x,y+(reduced?0:Math.sin(t*.9)*2),size,'Idle',0,t);c.restore()}
 c.restore();if(!reduced){const fade=Math.max(0,1-q*10)*.35;c.globalAlpha=fade;rect(c,0,0,W,H,'#0c1628');c.globalAlpha=1}return act;
}
